/// <summary>
/// TelemetryPurchaseOrderConfirm class extending methods of METTelemetryBase class
/// </summary>
final class METTelemetryPurchaseOrderConfirm extends METTelemetryBase
{
    private PurchTable purchTable;

}

Method.Source:
protected void populateProperties()
{
    // Setting elapsed milliseconds in the concrete implementation so that the implementer can decide what is the right way to get elapsed time.
    this.setElapsedMilliseconds();
    this.addBaseProperty(METApplicationInsightsEventProperties::PurchId, purchTable.PurchId);
    this.addBaseProperty(METApplicationInsightsEventProperties::PurchStatus, strFmt("%1", purchTable.PurchStatus));
    this.addBaseProperty(METApplicationInsightsEventProperties::DeliveryDate, DateTimeUtil::toStr(purchTable.DeliveryDate));
}
